// Generated by bottle-rulebook/stainless/sync-studio.mjs. Edit the source in bottle-rulebook, then sync.
// Stainless steel bottles and tumblers: the parametric family, its measurements, and rule
// evaluation. One ES module for Node (stainless/build.mjs, tests) and the Slot Studio bottles page,
// which gets a copy from stainless/sync-studio.mjs.
// Lengths are millimetres; z runs up from the base, r is the outer radius.
//
// Unlike the aluminum prototype (Python generator, JS mirror), this process is written once in JS.
// The forming limits it encodes are mostly estimates; each rule carries its confidence and source
// in stainless/rulebook.json.
const STEEL_G_PER_MM3 = 7.93e-3;
const STANDARD_MOUTHS = [40, 44, 48.5, 57.9, 62, 66]; // Zojirushi, Tiger, Hydro Flask std, HF wide, growler, Klean Kanteen
const WAIST_W = 0.16, BELLY_W = 0.26;

// ---------- parameters ----------
const PARAMS = [
  { name: 'form', kind: 'choice', choices: ['bottle', 'tumbler'], label: 'Form' },
  { name: 'wall', kind: 'choice', choices: ['single', 'double'], label: 'Wall' },
  { name: 'route', kind: 'choice', choices: ['tube', 'drawn'], label: 'Body route' },
  { name: 'mouth_id_mm', kind: 'float', lo: 20, hi: 72, unit: 'mm', label: 'Mouth inside diameter' },
  { name: 'body_d_mm', kind: 'float', lo: 50, hi: 115, unit: 'mm', label: 'Body diameter' },
  { name: 'body_h_mm', kind: 'float', lo: 80, hi: 300, unit: 'mm', label: 'Body height' },
  { name: 'taper', kind: 'float', lo: -0.08, hi: 0.12, unit: '', label: 'Taper (+ narrower at the top)' },
  { name: 'draft_deg', kind: 'float', lo: 0, hi: 9, unit: '°', label: 'Tumbler draft per side' },
  { name: 'waist', kind: 'float', lo: 0, hi: 0.26, unit: '', label: 'Waist depth' },
  { name: 'waist_pos', kind: 'float', lo: 0.3, hi: 0.75, unit: '', label: 'Waist position' },
  { name: 'belly', kind: 'float', lo: 0, hi: 0.26, unit: '', label: 'Belly bulge' },
  { name: 'belly_pos', kind: 'float', lo: 0.3, hi: 0.7, unit: '', label: 'Belly position' },
  { name: 'shoulder_h_mm', kind: 'float', lo: 10, hi: 75, unit: 'mm', label: 'Shoulder height' },
  { name: 'shoulder_p', kind: 'float', lo: 0.6, hi: 2.2, unit: '', label: 'Shoulder fullness' },
  { name: 'neck_len_mm', kind: 'float', lo: 8, hi: 32, unit: 'mm', label: 'Neck length' },
  { name: 'heel_r_mm', kind: 'float', lo: 2, hi: 14, unit: 'mm', label: 'Heel radius' },
  { name: 't_mm', kind: 'float', lo: 0.3, hi: 1.0, unit: 'mm', label: 'Wall (single)' },
  { name: 't_inner_mm', kind: 'float', lo: 0.06, hi: 0.65, unit: 'mm', label: 'Inner wall' },
  { name: 't_outer_mm', kind: 'float', lo: 0.2, hi: 0.95, unit: 'mm', label: 'Outer wall' },
  { name: 'gap_mm', kind: 'float', lo: 0.8, hi: 6.5, unit: 'mm', label: 'Vacuum gap' },
];
// Typical gauges from the research CSV, used for a sketch and for market products.
const TYPICAL = { single: { t_mm: 0.6 }, double: { t_inner_mm: 0.4, t_outer_mm: 0.5, gap_mm: 2.5 } };

const isDouble = (p) => p.wall === 'double';
// Steel and gap between the outer surface and the liquid.
const wallStack = (p) => (isDouble(p) ? p.t_outer_mm + p.gap_mm + p.t_inner_mm : p.t_mm);
const outerShellT = (p) => (isDouble(p) ? p.t_outer_mm : p.t_mm);

function linspace(a, b, n) {
  const out = new Array(n), step = (b - a) / (n - 1);
  for (let i = 0; i < n; i++) out[i] = a + i * step;
  out[n - 1] = b;
  return out;
}
function interp(x, xs, ys) {
  const n = xs.length;
  if (x <= xs[0]) return ys[0];
  if (x >= xs[n - 1]) return ys[n - 1];
  let lo = 0, hi = n - 1;
  while (hi - lo > 1) { const m = (lo + hi) >> 1; if (xs[m] <= x) lo = m; else hi = m; }
  return ys[lo] + ((ys[hi] - ys[lo]) / (xs[hi] - xs[lo])) * (x - xs[lo]);
}
const gauss = (u, c, w) => Math.exp(-(((u - c) / w) ** 2));

// ---------- profile ----------
function bodyRadius(p, u) {
  const R = p.body_d_mm / 2;
  let r;
  if (p.form === 'tumbler') {
    const drop = p.body_h_mm * Math.tan((p.draft_deg * Math.PI) / 180);
    r = R - drop * (1 - u); // widest at the rim
  } else {
    const tp = p.taper;
    r = R * (1 - Math.max(tp, 0) * u - Math.max(-tp, 0) * (1 - u));
  }
  return r - R * p.waist * gauss(u, p.waist_pos, WAIST_W) + R * p.belly * gauss(u, p.belly_pos, BELLY_W);
}

// Outer profile from the base contact ring to the mouth (bottle) or rim (tumbler).
function buildProfile(p) {
  const z = [], r = [];
  const bh = p.body_h_mm, heel = Math.min(p.heel_r_mm, bh * 0.2);
  for (const a of linspace(0, Math.PI / 2, 17)) {
    const zz = heel * (1 - Math.cos(a));
    z.push(zz); r.push(Math.max(bodyRadius(p, zz / bh) - heel + heel * Math.sin(a), 0.5));
  }
  for (const zz of linspace(heel, bh, 110).slice(1)) { z.push(zz); r.push(bodyRadius(p, zz / bh)); }
  if (p.form === 'bottle') {
    const rt = bodyRadius(p, 1), rn = p.mouth_id_mm / 2 + wallStack(p);
    for (const s of linspace(0, 1, 48).slice(1)) {
      z.push(bh + s * p.shoulder_h_mm);
      r.push(rn + (rt - rn) * 0.5 * (1 + Math.cos(Math.PI * s ** p.shoulder_p)));
    }
    const top = bh + p.shoulder_h_mm;
    for (const zz of linspace(top, top + p.neck_len_mm, 8).slice(1)) { z.push(zz); r.push(rn); }
  }
  return { z, r, form: p.form };
}

// A profile from a sketch read by fit.js (radius over height at fixed fractions), at height H.
function sketchProfile(sig, fracs, H, form) {
  return { z: fracs.map((f) => f * H), r: sig.map((v) => Math.max(v * H, 0.5)), form };
}
function scaleProfile(prof, s) {
  return { z: prof.z.map((v) => v * s), r: prof.r.map((v) => v * s), form: prof.form };
}
// Tumbler when the top is nearly as wide as the widest point; otherwise a necked bottle.
const formOf = (prof) => (prof.r[prof.r.length - 1] >= 0.85 * Math.max(...prof.r) ? 'tumbler' : 'bottle');

// ---------- measurements ----------
// cfg carries the wall system and gauges (a design's parameters, or typical values for a sketch).
function measure(prof, cfg, proc) {
  const { z, r } = prof;
  const n = z.length, H = z[n - 1];
  const dbl = isDouble(cfg), w = wallStack(cfg), tOut = outerShellT(cfg);
  let maxR = 0;
  for (const v of r) maxR = Math.max(maxR, v);

  // Cavity: the outer profile less the wall stack, from the floor to the mouth.
  const floor = w, NS = 240;
  const zc = linspace(floor, H, NS), area = zc.map((zz) => { const rc = Math.max(interp(zz, z, r) - w, 0); return Math.PI * rc * rc; });
  const vol = [0], mom = [0];
  for (let i = 1; i < NS; i++) {
    const slab = ((area[i] + area[i - 1]) / 2) * (zc[i] - zc[i - 1]);
    vol.push(vol[i - 1] + slab);
    mom.push(mom[i - 1] + slab * (zc[i] + zc[i - 1]) / 2);
  }
  const brim = vol[NS - 1];
  const nominal = brim / (1 + proc.brim_over_nominal);

  // Steel: thin shells along the profile plus base discs.
  let steelV = 0, steelM = 0;
  const shell = (off, t) => {
    for (let i = 1; i < n; i++) {
      const ds = Math.hypot(z[i] - z[i - 1], r[i] - r[i - 1]);
      const rm = Math.max((r[i] + r[i - 1]) / 2 - off - t / 2, 0);
      const dv = 2 * Math.PI * rm * t * ds;
      steelV += dv; steelM += dv * (z[i] + z[i - 1]) / 2;
    }
    const disc = Math.PI * Math.max(r[0] - off, 0) ** 2 * t;
    steelV += disc; steelM += disc * (off + t / 2);
  };
  shell(0, tOut);
  if (dbl) shell(cfg.t_outer_mm + cfg.gap_mm, cfg.t_inner_mm);
  const steelG = steelV * STEEL_G_PER_MM3;
  const steelZ = steelM / steelV;

  const rTop = r[n - 1];
  const mouthId = 2 * (rTop - w);
  const isTumbler = prof.form === 'tumbler';
  const lidG = isTumbler ? proc.lid_g_tumbler : mouthId < 52 ? proc.lid_g_narrow : proc.lid_g_wide;
  const lidZ = H + 12;

  // Stability on the 10° incline: tip angle about the base contact ring, full, half and empty.
  const rContact = r[0];
  const tips = [1, 0.5, 0].map((f) => {
    const v = nominal * f;
    let wg = 0, wz = 0;
    if (v > 0) {
      let i = 1;
      while (i < NS - 1 && vol[i] < v) i++;
      const fr = (v - vol[i - 1]) / Math.max(vol[i] - vol[i - 1], 1e-12);
      wg = v * 1e-3; wz = (mom[i - 1] + fr * (mom[i] - mom[i - 1])) / v;
    }
    const zcom = (steelG * steelZ + lidG * lidZ + wg * wz) / (steelG + lidG + wg);
    return (Math.atan2(rContact, zcom) * 180) / Math.PI;
  });

  // Where forming happens. A bottle's top is spun down from the shoulder: walk down from the
  // mouth while the radius keeps growing. Below that, everything wider than the narrowest
  // body section is bulged out of a tube that size (heel corners excluded).
  let s = n - 1;
  if (!isTumbler) while (s > 0 && r[s - 1] >= r[s] - 1e-6) s--;
  const heelZone = Math.min(0.08 * H, 15);
  let tubeR = Infinity, bodyMaxR = 0;
  for (let i = 0; i <= s; i++) {
    if (z[i] < heelZone) continue;
    tubeR = Math.min(tubeR, r[i]); bodyMaxR = Math.max(bodyMaxR, r[i]);
  }
  if (!isFinite(tubeR)) { tubeR = r[s]; bodyMaxR = r[s]; }
  let expansion = bodyMaxR / tubeR - 1;
  if (cfg.route === 'drawn') {
    // A drawn cup is straight or tapered; only bulges beyond the line from its foot to its top need a bulge.
    let i0 = 0; while (i0 < s && z[i0] < heelZone) i0++;
    let e = 0;
    for (let i = i0; i <= s; i++) {
      const f = s > i0 ? (z[i] - z[i0]) / (z[s] - z[i0]) : 0;
      e = Math.max(e, r[i] / (r[i0] + f * (r[s] - r[i0])) - 1);
    }
    expansion = e;
  }
  const shoulderD = 2 * r[s], neckOd = 2 * rTop;
  const passes = isTumbler || neckOd >= shoulderD ? 0 : Math.ceil(Math.log(neckOd / shoulderD) / Math.log(1 - proc.spin_step) - 1e-9);
  const thin = (t) => t * Math.pow(1 + Math.max(expansion, 0), -proc.thinning_exponent);
  const hOverD = H / (2 * maxR);
  const drawStages = 1 + Math.ceil(Math.max(0, hOverD - 0.6) / proc.draw_hd_per_stage - 1e-9);

  // Heat retention, double wall only: a rough lumped model whose heat leak is the lid (by mouth
  // area) plus the walls (by capacity), fitted to Tiger's published 6 h end temperatures.
  let t6 = null;
  if (dbl && nominal > 1) {
    const mouthCm2 = Math.PI * (Math.max(mouthId, 0) / 20) ** 2;
    const ml = nominal / 1000;
    const ua = proc.heat_lid_w_per_k_cm2 * mouthCm2 + proc.heat_wall_w_per_k_ml * ml;
    t6 = 20 + 75 * Math.exp((-6 * 3600 * ua) / (4.186 * ml));
  }

  let lowerMax = 0;
  for (let i = 0; i < n; i++) if (z[i] <= proc.cup_holder_depth_mm) lowerMax = Math.max(lowerMax, r[i]);
  const family = isTumbler
    ? (mouthId >= 75 && mouthId <= 105 ? 'rim' : 'rim-off')
    : mouthId >= 40 && mouthId <= 49 ? 'narrow' : mouthId >= 57 && mouthId <= 66 ? 'wide' : 'off';

  const lidH = isTumbler ? proc.lid_h_tumbler_mm : mouthId < 52 ? proc.lid_h_narrow_mm : proc.lid_h_wide_mm;
  return {
    capacity_brimful_ml: brim / 1000,
    capacity_ml: nominal / 1000,
    height_mm: H,
    max_d_mm: 2 * maxR,
    h_over_d: hOverD,
    h_over_d_lid: (H + lidH) / (2 * maxR),
    mouth_id_mm: mouthId,
    mouth_body: mouthId / (2 * maxR),
    neck_od_mm: neckOd,
    shoulder_d_mm: shoulderD,
    tube_d_mm: 2 * tubeR,
    bulge_expansion: expansion,
    spin_passes: passes,
    draw_stages: cfg.route === 'drawn' ? drawStages : 0,
    finished_wall_mm: thin(tOut),
    t_single_mm: dbl ? null : cfg.t_mm,
    t_inner_mm: dbl ? cfg.t_inner_mm : null,
    t_outer_mm: dbl ? cfg.t_outer_mm : null,
    gap_mm: dbl ? cfg.gap_mm : null,
    outer_minus_inner_mm: dbl ? cfg.t_outer_mm - cfg.t_inner_mm : null,
    thread_wall_mm: isTumbler ? null : tOut,
    mouth_on_family: family === 'narrow' || family === 'wide' || family === 'rim' ? 1 : 0,
    mouth_family: family,
    steel_g: steelG,
    mass_g: steelG + lidG,
    g_per_ml: (steelG + lidG) / Math.max(nominal / 1000, 1),
    tip_min_deg: Math.min(...tips),
    heat_6h_c: t6,
    heat_required_c: dbl ? heatRequired(nominal / 1000) : null,
    lower_band_d_mm: 2 * lowerMax,
    body_d_mm: 2 * bodyMaxR,
  };
}

// EN 12546-1 minimum end temperature after 6 h, by capacity band.
function heatRequired(ml) {
  if (ml <= 200) return 60;
  if (ml <= 400) return 65;
  if (ml <= 600) return 70;
  if (ml <= 800) return 75;
  if (ml <= 1200) return 78;
  return 80;
}

// ---------- rules ----------
function rawMargin(rule, v) {
  if (rule.op === '<=') return rule.limit - v;
  if (rule.op === '>=') return v - rule.limit;
  if (rule.op === 'between') return Math.min(v - rule.limit[0], rule.limit[1] - v);
  throw new Error('unknown op ' + rule.op);
}
function applies(rule, ctx) {
  const a = rule.applies || {};
  for (const k of Object.keys(a)) if (!a[k].includes(ctx[k])) return false;
  return true;
}
// Rules that apply to this design and are switched on; a rule's limit may differ by form.
function activeRules(book, ctx, state) {
  const out = [];
  for (const r of book.rules) {
    const st = state && state[r.id];
    if (st && st.on === false) continue;
    if (!st && r.default_on === false) continue;
    if (r.market && (!state || state.__market !== r.market) && !(st && st.on)) continue;
    if (!applies(r, ctx)) continue;
    let limit = st && st.limit !== undefined ? st.limit : r.limit;
    if (r.by_form && !(st && st.limit !== undefined)) limit = r.by_form[ctx.form];
    out.push(Object.assign({}, r, { limit }));
  }
  return out;
}
// Every applicable rule's margin and pass flag, plus a verdict per tier.
function evaluate(m, ctx, book, state) {
  const rules = activeRules(book, ctx, state);
  const res = { rules: [], fails: { make: [], standard: [], tooling: [], precedent: [], use: [] }, minNorm: Infinity };
  for (const r of rules) {
    let v = r.measure === 'heat_margin_c' ? (m.heat_6h_c === null ? null : m.heat_6h_c - m.heat_required_c) : m[r.measure];
    if (v === null || v === undefined) continue;
    const raw = rawMargin(r, v);
    const ok = raw >= 0;
    res.rules.push({ rule: r, value: v, raw, ok });
    if (!ok) res.fails[r.tier].push(r.id);
    if (r.tier === 'make' || r.tier === 'standard') res.minNorm = Math.min(res.minNorm, raw / r.scale);
  }
  res.canMake = res.fails.make.length === 0;
  res.feasible = res.canMake && res.fails.standard.length === 0 && res.fails.use.length === 0;
  return res;
}
const ctxOf = (p) => ({ form: p.form, wall: p.wall, route: p.route });

// ---------- features for the design-space map ----------
const SHAPE_FRACS = [0.05, 0.15, 0.25, 0.35, 0.45, 0.55, 0.65, 0.75, 0.85, 0.95];
const GROUPS = [
  { id: 'shape', label: 'Silhouette' },
  { id: 'proportion', label: 'Proportion' },
  { id: 'size', label: 'Size' },
  { id: 'mouth', label: 'Neck & mouth' },
  { id: 'wall', label: 'Wall system' },
  { id: 'process', label: 'Process' },
];
// [group, name, value] triples; continuous values are standardized later.
function features(prof, p, m) {
  const H = prof.z[prof.z.length - 1], maxR = m.max_d_mm / 2;
  const out = [];
  for (const f of SHAPE_FRACS) out.push(['shape', 'r@' + f, interp(f * H, prof.z, prof.r) / maxR]);
  out.push(['shape', 'tumbler', p.form === 'tumbler' ? 1 : 0]);
  out.push(['proportion', 'h_over_d', m.h_over_d]);
  out.push(['size', 'log_capacity', Math.log(Math.max(m.capacity_ml, 20))]);
  out.push(['size', 'height', m.height_mm]);
  out.push(['size', 'diameter', m.max_d_mm]);
  out.push(['mouth', 'mouth_id', m.mouth_id_mm]);
  out.push(['mouth', 'mouth_body', m.mouth_body]);
  for (const fam of ['narrow', 'wide', 'off', 'rim']) out.push(['mouth', 'fam_' + fam, m.mouth_family.startsWith(fam) ? 1 : 0]);
  out.push(['wall', 'double', isDouble(p) ? 1 : 0]);
  out.push(['wall', 'gap', isDouble(p) ? p.gap_mm : 0]);
  out.push(['wall', 'steel', isDouble(p) ? p.t_inner_mm + p.t_outer_mm : p.t_mm]);
  out.push(['process', 'drawn', p.route === 'drawn' ? 1 : 0]);
  out.push(['process', 'expansion', Math.min(m.bulge_expansion, 1.5)]);
  out.push(['process', 'passes', Math.min(m.spin_passes, 10)]);
  return out;
}

export {
PARAMS, TYPICAL, STANDARD_MOUTHS, GROUPS, SHAPE_FRACS,
wallStack, interp, linspace, bodyRadius, buildProfile, sketchProfile, scaleProfile, formOf,
measure, heatRequired, rawMargin, activeRules, evaluate, ctxOf, features,
};
